// Block types Anthropic forbids cache_control on. Mirrors Claude Code's
// assistantMessageToMessageParam exclusion list (claude.ts:~648).
const CACHE_CONTROL_FORBIDDEN_TYPES = new Set(["thinking", "redacted_thinking"]);

// Anthropic treats an assistant turn that carries thinking/redacted_thinking
// blocks as immutable: with the interleaved-thinking beta, adding a
// cache_control marker to ANY block in it (even a tool_use sibling) trips a
// 400 "thinking or redacted_thinking blocks in the latest assistant message
// cannot be modified". Detect such turns so breakpoint placement skips them
// and keeps rolling markers on user/tool_result turns, matching Claude Code.
function messageHasThinking(content) {
  return Array.isArray(content) && content.some((b) => CACHE_CONTROL_FORBIDDEN_TYPES.has(b?.type));
}

/**
 * Add prompt-cache breakpoints to the upstream request.
 *
 * CACHE CRITICAL: marker placement controls subscription burn. In OAuth mode
 * Pi's real system prompt is moved to messages[0] as <system-context>, so the
 * bridge must not spend a marker on the tiny Claude Code identity string while
 * leaving messages[0] unmarked. Keep the fixed prefix stable and put dynamic
 * transcript growth behind rolling message markers.
 *
 * Anthropic allows up to 4 markers per request. Target layout:
 *   - messages[0] <system-context> marker in OAuth mode, or system marker from
 *     the client in API-key mode
 *   - tools[-1].cache_control caches the full tool array
 *   - last two cacheable message blocks cache the rolling transcript body
 *
 * Idempotent: skips blocks that already carry cache_control.
 */
/**
 * Rewrite any incoming bare `cache_control: { type: "ephemeral" }` to add
 * `ttl: "1h"`. Catches markers from clients that don't know about extended
 * cache (pi coding-agent without cacheRetention='long', Claude Code CLI, etc).
 * Idempotent — leaves blocks that already specify a ttl alone.
 */
function applyExtendedCacheTtl(params) {
  if (!EXTENDED_CACHE) return params;
  const fix = (cc) =>
    cc && typeof cc === "object" && cc.type === "ephemeral" && !cc.ttl
      ? { ...cc, ttl: "1h" }
      : cc;
  const fixBlocks = (arr) =>
    Array.isArray(arr)
      ? arr.map((b) => (b?.cache_control ? { ...b, cache_control: fix(b.cache_control) } : b))
      : arr;
  const next = { ...params };
  if (Array.isArray(params.system)) next.system = fixBlocks(params.system);
  if (Array.isArray(params.tools)) next.tools = fixBlocks(params.tools);
  if (Array.isArray(params.messages)) {
    next.messages = params.messages.map((m) =>
      Array.isArray(m?.content) ? { ...m, content: fixBlocks(m.content) } : m,
    );
  }
  return next;
}

// Anthropic hard-caps cache_control markers at 4 per request. When pi or
// any earlier bridge transform adds a marker AND we then wrap the system
// prompt into a <system-context> user message that also carries a marker,
// the request can exceed the cap and Anthropic returns 400. This clamp is
// applied right before the upstream POST as a final safety net. Markers are
// stripped from the *latest* message blocks backward: those breakpoints have
// the smallest cached-prefix payback (the rolling tail), so dropping them
// loses the least cache value. System and tools markers are preserved.
const MAX_CACHE_CONTROLS = 4;

function clampCacheControls(params) {
  let count = countCacheControls(params);
  if (count <= MAX_CACHE_CONTROLS) return params;

  const next = { ...params };
  if (!Array.isArray(next.messages)) return next;
  const messages = [...next.messages];
  // Walk messages from tail to head, then blocks within each message from
  // tail to head, stripping cache_control until under the cap.
  for (let i = messages.length - 1; i >= 0 && count > MAX_CACHE_CONTROLS; i--) {
    const message = messages[i];
    const content = message?.content;
    if (!Array.isArray(content)) continue;
    const blocks = [...content];
    let mutated = false;
    for (let j = blocks.length - 1; j >= 0 && count > MAX_CACHE_CONTROLS; j--) {
      const block = blocks[j];
      if (!block?.cache_control) continue;
      const { cache_control: _cc, ...rest } = block;
      blocks[j] = rest;
      mutated = true;
      count -= 1;
    }
    if (mutated) messages[i] = { ...message, content: blocks };
  }
  next.messages = messages;
  if (count > MAX_CACHE_CONTROLS) {
    // Last resort: trim tools markers (preserve system block markers as the
    // highest-value anchor).
    if (Array.isArray(next.tools)) {
      const tools = next.tools.map((t) => {
        if (count <= MAX_CACHE_CONTROLS) return t;
        if (!t?.cache_control) return t;
        const { cache_control: _cc, ...rest } = t;
        count -= 1;
        return rest;
      });
      next.tools = tools;
    }
  }
  return next;
}

function countCacheControls(params) {
  let count = 0;
  const countBlocks = (blocks) => {
    if (!Array.isArray(blocks)) return;
    for (const block of blocks) if (block?.cache_control) count += 1;
  };
  countBlocks(Array.isArray(params.system) ? params.system : undefined);
  countBlocks(params.tools);
  if (Array.isArray(params.messages)) {
    for (const message of params.messages) countBlocks(Array.isArray(message?.content) ? message.content : undefined);
  }
  return count;
}

function addCacheBreakpoints(params) {
  let remainingMarkers = Math.max(0, 4 - countCacheControls(params));

  if (remainingMarkers > 0 && Array.isArray(params.tools) && params.tools.length > 0) {
    const tools = [...params.tools];
    // Find the last tool that doesn't have defer_loading — the API rejects
    // cache_control + defer_loading on the same tool definition.
    let cacheIdx = -1;
    for (let i = tools.length - 1; i >= 0; i--) {
      if (!tools[i].defer_loading) { cacheIdx = i; break; }
    }
    if (cacheIdx >= 0 && !tools[cacheIdx].cache_control) {
      tools[cacheIdx] = { ...tools[cacheIdx], cache_control: EPHEMERAL };
      params = { ...params, tools };
      remainingMarkers -= 1;
    }
  }

  if (remainingMarkers > 0 && Array.isArray(params.messages) && params.messages.length > 0) {
    const messages = [...params.messages];
    for (let msgIdx = messages.length - 1; msgIdx >= 0 && remainingMarkers > 0; msgIdx--) {
      const message = messages[msgIdx];
      const content = message?.content;
      if (typeof content === "string") {
        messages[msgIdx] = {
          ...message,
          content: [{ type: "text", text: content, cache_control: EPHEMERAL }],
        };
        remainingMarkers -= 1;
        continue;
      }
      if (!Array.isArray(content) || content.length === 0) continue;
      // Never mark an assistant turn that carries thinking blocks — see
      // messageHasThinking. A marker anywhere in it triggers the upstream 400.
      if (message.role === "assistant" && messageHasThinking(content)) continue;

      const blocks = [...content];
      for (let blockIdx = blocks.length - 1; blockIdx >= 0; blockIdx--) {
        const block = blocks[blockIdx];
        if (!block || CACHE_CONTROL_FORBIDDEN_TYPES.has(block.type)) continue;
        if (block.cache_control) break;
        blocks[blockIdx] = { ...block, cache_control: EPHEMERAL };
        messages[msgIdx] = { ...message, content: blocks };
        remainingMarkers -= 1;
        break;
      }
    }
    params = { ...params, messages };
  }

  return params;
}

function wantsCacheDisabled(headers) {
  const value = headers?.["x-bridge-cache-retention"] || headers?.["x-pi-cache-retention"];
  return typeof value === "string" && value.toLowerCase() === "none";
}

// Anthropic refuses to cache prefixes below a minimum input-token count
// (1024 for sonnet/opus, 2048 for haiku). A cache_control marker on such a
// prefix still counts as a creation attempt in our telemetry but never pays
// back — telemetry calls this the "tiny-probe" pattern (msgs=1 tools=0 in
// the cache-waste breakdown). 4096 bytes is a conservative floor: at
// ~4 chars/token even pathologically dense content stays under 1024 tokens,
// so we strip markers on anything below it for every model. Above 4 kB we
// keep markers; sonnet/opus benefit immediately, haiku may still miss on
// some borderline prefixes but the lost cache_control is mild compared to
// over-stripping legitimate sessions.
const MIN_CACHEABLE_PREFIX_BYTES = 4 * 1024;

function estimatePrefixBytes(params) {
  let bytes = 0;
  const addBlock = (block) => {
    if (block == null) return;
    if (typeof block === "string") { bytes += block.length; return; }
    if (typeof block.text === "string") { bytes += block.text.length; return; }
    // Tool definitions, tool_use, tool_result and unknown shapes: stringify
    // for a stable upper-bound estimate without recursing into every field.
    bytes += JSON.stringify(block).length;
  };
  const addBlocks = (arr) => { if (Array.isArray(arr)) for (const b of arr) addBlock(b); };
  if (typeof params.system === "string") bytes += params.system.length;
  else addBlocks(params.system);
  addBlocks(params.tools);
  if (Array.isArray(params.messages)) {
    for (const m of params.messages) {
      const c = m?.content;
      if (typeof c === "string") bytes += c.length;
      else addBlocks(c);
    }
  }
  return bytes;
}

function isPrefixTooSmallToCache(params) {
  return estimatePrefixBytes(params) < MIN_CACHEABLE_PREFIX_BYTES;
}

function shouldAddBridgeCacheBreakpoints(params, meta = {}) {
  if (Array.isArray(params.tools) && params.tools.length > 0) return true;

  // Anonymous/source-only tool-less requests are usually one-shot side probes
  // (Claude Code summaries, titles, health/classifier calls). Adding bridge
  // cache markers to those produced repeated read=0/write=30k bursts with no
  // reuse. Keep auto-markers for attributed sessions, where a no-tool chat can
  // still benefit from a rolling transcript cache.
  return Boolean(
    meta.piSessionId ||
    meta.sessionId ||
    meta.paperclipRunId ||
    meta.agentId ||
    meta.childAgent !== undefined
  );
}

// Extract the first text payload from a message's content (string or blocks).
function firstMessageText(content) {
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    const t = content.find((b) => b && b.type === "text" && typeof b.text === "string");
    return t ? t.text : "";
  }
  return "";
}

// Rewrite a trailing sentinel-tagged message into a real mid-conversation
// {role:"system"} entry. Conservative by design: only the LAST message is
// considered, and only when the message before it is a plain user message (so
// Anthropic's placement rules — system must follow a user message and end the
// array — always hold). Otherwise the sentinel is stripped and the message is
// left as a normal user turn, so an over-eager extension can never produce an
// invalid request.
function rewriteMidConversationSystemMessages(messages) {
  if (!Array.isArray(messages) || messages.length === 0) return messages;
  const lastIdx = messages.length - 1;
  const last = messages[lastIdx];
  if (!last || last.role !== "user") return messages;
  const text = firstMessageText(last.content);
  if (!text.startsWith(MID_SYSTEM_SENTINEL)) return messages;
  const body = text.slice(MID_SYSTEM_SENTINEL.length);
  const prev = lastIdx > 0 ? messages[lastIdx - 1] : null;
  if (prev && prev.role === "user" && body.trim().length > 0) {
    return [...messages.slice(0, lastIdx), { role: "system", content: body }];
  }
  // Fallback: drop the sentinel, keep it as an ordinary user message.

