import { createJiti } from "jiti";

const jiti = createJiti(import.meta.url, { interopDefault: true, fsCache: false });
const { normalizeToolName } = await jiti.import("../../extensions/tool-search/src/catalog.ts");

export const PROMPT_HEALTH_THRESHOLDS = {
  // Total first-turn payload (system + tools + messages[0]) est = bytes/4. A
  // healthy current install lands ~30.2–30.8k: the eager toolset (~9.8k), the
  // deferred-tools list incl. the consented Workflow tool (~1.5k), and the
  // session-stable available_skills routing index (~21kB ≈ 5.3k tokens). Was
  // 30_000 — sized before the Workflow tool joined the profile and before the
  // skills byte budget was raised 8k→28k (a2b9145), which together push the
  // healthy baseline just over 30k. Raised to 33_000 (≈2k headroom over the
  // observed peak) 2026-05-29; still catches a real ~10% bloat regression.
  maxTotalPromptTokens: 33_000,
  // 15 since 2026-05-30: + EnterPlanMode/ExitPlanMode (pi-mode, WS13) are eager
  // for CC parity — the model calls them directly to enter plan mode and to
  // request approval to exit (CC's plan tools are always available, not
  // discovered). One-time Luke-approved cache rebaseline. Was 13 (AskUserQuestion
  // WS9), 12 before that.
  maxEagerTools: 15,
  maxActiveTools: 40,
  // available_skills is the cached, session-stable parent-skill routing index
  // (children defer under parents via skill_search). Trigger-rich descriptions
  // are load-bearing for routing, not fat — a healthy ~26-parent install is
  // ~21 kB. Budget catches real regressions: child-deferral breaking (~56
  // skills ≈ 44 kB) or inline SKILL bodies leaking (separate inline_skill_body
  // check). Was 8_000 (sized for a far smaller install); raised 2026-05-29.
  maxAvailableSkillsBytes: 28_000,
};

export function auditPromptDump(dump) {
  const messages0Content = dump.messages?.[0]?.content;
  const messages0 = messageContentText(messages0Content);
  const tools = dump.tools ?? [];
  const activeTools = tools.map((tool) => String(tool.name));
  const eagerTools = tools.filter((tool) => tool.defer_loading !== true);
  const eagerCapabilities = new Set(eagerTools.map((tool) => normalizeToolName(String(tool.name))));
  const deferredCapabilities = parseDeferredTools(messages0).map(normalizeToolName);
  const duplicateCapabilities = [...new Set(deferredCapabilities.filter((name) => eagerCapabilities.has(name)))].sort();
  const availableSkills = extractBlock(messages0, "available_skills");
  const payloadBytes = Buffer.byteLength(JSON.stringify(dump));

  return {
    estTotalTokens: Math.floor(payloadBytes / 4),
    activeToolCount: activeTools.length,
    eagerToolCount: eagerTools.length,
    nativeDeferredToolCount: tools.filter((tool) => tool.defer_loading === true).length,
    duplicateCapabilities,
    inlineSkillBodyHits: (messages0.match(/^# SKILL\b|^# Skill\b/gm) ?? []).length,
    multilineSkillBlocks: countMultilineSkillBlocks(messages0),
    availableSkillsBytes: Buffer.byteLength(availableSkills),
    systemContextPresent: messages0.includes("<system-context>"),
    messages0HasCacheControl: Array.isArray(messages0Content)
      ? messages0Content.some((block) => block?.cache_control)
      : false,
    systemHasCacheControl: Array.isArray(dump.system)
      ? dump.system.some((block) => block?.cache_control)
      : false,
  };
}

export function promptHealthWarnings(audit, thresholds = PROMPT_HEALTH_THRESHOLDS) {
  const warnings = [];
  const maxEagerTools = thresholds.maxEagerTools ?? thresholds.maxActiveTools;
  if (audit.estTotalTokens > thresholds.maxTotalPromptTokens) {
    warnings.push("total_prompt_over_soft_cap");
  }
  if (audit.eagerToolCount > maxEagerTools) {
    warnings.push("eager_tool_schema_budget_exceeded");
  }
  if (audit.duplicateCapabilities.length > 0) {
    warnings.push("active_deferred_double_billing");
  }
  if (audit.nativeDeferredToolCount === 0 && audit.eagerToolCount > 5) {
    warnings.push("native_deferred_missing");
  }
  if (audit.inlineSkillBodyHits > 0 || audit.multilineSkillBlocks > 0) {
    warnings.push("inline_skill_body");
  }
  if (audit.availableSkillsBytes > thresholds.maxAvailableSkillsBytes) {
    warnings.push("available_skills_over_budget");
  }
  if (audit.systemContextPresent && !audit.messages0HasCacheControl) {
    warnings.push("system_context_missing_cache_control");
  }
  return warnings;
}

export function messageContentText(content) {
  if (typeof content === "string") return content;
  if (Array.isArray(content)) {
    return content.map((block) => typeof block === "string" ? block : block?.text ?? "").join("\n");
  }
  return "";
}

function parseDeferredTools(text) {
  const block = extractBlock(text, "deferred-tools");
  return [...block.matchAll(/^- ([A-Za-z_][A-Za-z0-9_]*)/gm)].map((match) => match[1]);
}

function extractBlock(text, tag) {
  const open = `<${tag}>`;
  const close = `</${tag}>`;
  const openIndex = text.indexOf(open);
  if (openIndex < 0) return "";
  const closeIndex = text.indexOf(close, openIndex);
  if (closeIndex < 0) return text.slice(openIndex + open.length);
  return text.slice(openIndex + open.length, closeIndex);
}

function countMultilineSkillBlocks(text) {
  const block = extractBlock(text, "available_skills");
  return [...block.matchAll(/<skill>([\s\S]*?)<\/skill>/g)].filter((match) => match[1].includes("\n")).length;
}

