118	function memVars(slug: string, originSessionId: string): Record<string, string> {
119		return { PROJECT_SLUG: slug, ORIGIN_SESSION_ID: originSessionId, MEMORY_ROOT: memoryRoot(), PROFILE_DIR: profileDir(), PROJECT_DIR: projectDir(slug) };
120	}
121	export function buildParentMemoryPromptSection(slug: string, originSessionId: string): string {
122		const vars = memVars(slug, originSessionId);
123		return [
124			"# Memory",
125			`You have a persistent memory system rooted at \`${vars.MEMORY_ROOT}/\`.`,
126			"Use memory when the user asks to recall/remember, or when injected memory is clearly relevant. Treat memories as stale hints: verify file paths, functions, flags, and current repo state before acting.",
127			"Do not save secrets, transient task state, derivable repo facts, git history, debugging recipes, or anything already documented in MEMORY.md, AGENTS.md, CLAUDE.md, or skill files.",
128			"If the user explicitly asks you to save or forget a memory inline, use `write`/`edit` to update a typed markdown file plus the matching MEMORY.md index. Types: `user`, `feedback`, `project`, `reference`. Filenames must start with the type, e.g. `feedback_no_db_mocks.md`. Include frontmatter: `name`, `description`, `type`, `originSessionId`.",
129			`Save cross-project memories under \`${vars.PROFILE_DIR}/\`; save project-specific memories under \`${vars.PROJECT_DIR}/\`. Current project slug: \`${slug}\`. Current pi session id: \`${originSessionId}\`.`,
130			"For detailed save rules, load the `pi-memory-save` skill before writing non-trivial memories. Background extraction normally handles memory writes automatically.",
131		].join("\n\n");
132	}
133	export function buildFullSavePromptSection(slug: string, originSessionId: string): string {
134		const parts = [
135			`# Memory\n\nYou have a persistent memory system rooted at \`${memoryRoot()}/\`.`,
136			loadPrompt("types-individual.md"),
137			loadPrompt("what-not-to-save.md"),
138			fill(loadPrompt("save-instructions.md"), memVars(slug, originSessionId)),
139			loadPrompt("recall-guidance.md"),
140		];
