309	/** Load + memoise the stable profile snapshot. `null` = no profile content. */
310	async function getProfileSnapshot(): Promise<ProfileSnapshot | null> {
311		if (_profileSnapshot !== undefined) return _profileSnapshot;
312		try {
313			const { content } = await loadProfileContext({
314				maxBytes: SESSION_START_MAX_BYTES,
315				maxFiles: SESSION_START_MAX_FILES,
316			});
317			const trimmed = content.trim();
318			if (!trimmed) {
319				_profileSnapshot = null;
320				return null;
321			}
322			_profileSnapshot = {
323				block: `${PROFILE_BLOCK_OPEN}\n${trimmed}\n</project_instructions>`,
324				content: trimmed,
325				safe: isProfileBaseSafe(trimmed),
326			};
327		} catch {
328			_profileSnapshot = null;
329		}
330		return _profileSnapshot;
