// --- before_agent_start -------------------------------------------------
// Cache-sensitive handler.
//   first call  → awaits dispatchSessionStart only (fast, ≤150ms) for the
//                 one-shot deterministic persistent-memory systemPrompt append.
//   active recall prefetch may be awaited for lookup-style prompts, but the
//                 message is delivered only through the context hook.
//   NEVER returns per-turn/dynamic systemPrompt content after the first call.
pi.on(
	"before_agent_start",
	async (event: BeforeAgentStartEvent, ctx): Promise<BeforeAgentStartEventResult | void> => {
		if (isDreamMemoryDisabled()) {
			ctx.ui?.setStatus("dream-memory", ctx.ui.theme.fg("dim", "🧠 off"));
			return undefined;
		}
		// Sub-agent guard (session-level): Pi children spawned with
		// `pi --source child-agent` or in-process child sessions created
		// by the built-in `agent` tool / `ctx.forkAgent` must not run
		// recall, dream-notify, or persistent-memory inject — their system
		// prompt is owned by the spawning agent.
		if (isMemorySubAgent(ctx)) {
			ctx.ui?.setStatus("dream-memory", ctx.ui.theme.fg("dim", "🧠 sub-agent"));
			return undefined;
		}
		// In-process delegated turns: the built-in `agent` tool /
		// `ctx.forkAgent` set `source: "child-agent"`. Extension-initiated
		// prompts (steer / sendCustomMessage from a hook) use `"extension"`.
		// Neither is user input, so skip recall + persistent-memory inject.
		// Was the original bug: BeforeAgentStartEvent didn't carry source,
		// so delegated runs re-entered the rerank sidecar and timed out.
		// Cast through unknown to read `source` even on older pi versions
		// where BeforeAgentStartEvent doesn't declare it (added in pi-mono-fork
		// after 0.74.1). Falls through cleanly when the field is undefined.
		const evSrc = (event as unknown as { source?: string }).source;
		if (evSrc === "child-agent" || evSrc === "extension") {
			ctx.ui?.setStatus("dream-memory", ctx.ui.theme.fg("dim", "🧠 sub-agent"));
			return undefined;
		}
		// Fire-and-forget: surface a one-line notify if a background dream
		// finished since this session's last check.
		void notifyOnNewDream(ctx);
		const cfg = await loadRecallConfig();

		// Show spinner immediately so the TUI doesn't look frozen.
		const breaker = await readBreakerState().catch(() => undefined);
		if (!breaker || !isBreakerOpen(breaker, cfg, Date.now())) {
			ctx.ui?.setStatus("dream-memory", ctx.ui.theme.fg("dim", "🧠 …"));
		}

		if (!firstBeforeAgentStartSeen) {
			firstBeforeAgentStartSeen = true;

			// CACHE CRITICAL: persistent memory is the only dream-memory
			// content allowed in systemPrompt. It must be a deterministic
			// profile + project snapshot for this cwd/project slug: no dates,
			// session ids, counters, file mtimes, active-recall output, or
			// other per-message values. Dream runs may update the files on
			// disk, but live sessions keep their first-turn bytes stable; new
			// sessions pick up changed memory by content, not by wall-clock
			// labels like "today".
			//
			// Await only session-start — it's fast (≤150ms budget) and
			// provides the persistent-memory payload. Keep the heavier
			// UserPromptSubmit search out of this critical path.
			const sess = await dispatchSessionStart(baseHook("SessionStart", ctx));
			if (typeof event.prompt === "string" && event.prompt.trim().length > 0) {
				ensurePassiveRecall(event.prompt, ctx, cfg, { first_turn: true });
			}

			lastCfg = cfg;
			ensureRecallPrefetch(event.prompt, ctx, cfg);
			if (shouldAwaitActiveRecall(event.prompt)) {
				await waitForRecallPreflight(pendingRecall);
			}

			// Profile normally rides in the cacheable base (placed by the
			// systemPrompt:build filter above). Only fall back to the
			// volatile tail when the filter could not place it safely
			// (unsafe content / no <project_context>), so no memory is lost.
			const snap = await getProfileSnapshot();
			const fallbackProfile = !profilePlacedInBase && snap?.content ? snap.content : "";
			const tail = [fallbackProfile, sess.stdout].filter(Boolean).join("\n\n");
			if (!tail) return undefined;
			return {
				systemPrompt: `${event.systemPrompt}\n\n<persistent-memory>\n${tail}\n</persistent-memory>`,
			};
		}

		// Subsequent turns: prefetch recall, optionally wait briefly for
		// lookup-style prompts, and let the context hook deliver it at the tail
		// of the per-call model context.
		ensurePassiveRecall(event.prompt, ctx, cfg);
		lastCfg = cfg;
		ensureRecallPrefetch(event.prompt, ctx, cfg);
		if (shouldAwaitActiveRecall(event.prompt)) {
			await waitForRecallPreflight(pendingRecall);
		}
		return undefined;
	},
);

