// static usage guidance + cwd-derived paths, with ZERO per-session volatile data
// (no session id, dates, or counters). This block is appended to the system
// prompt every session; any unique value here lands in the cached prefix and
// bursts the cross-session prompt cache for every same-cwd session. The
// originSessionId still rides the extractor's per-call user prompt
// (buildExtractPrompt) — never this cached block. Regression: test/unit.test.ts
// asserts the output is byte-stable and carries no session id.
export function buildParentMemoryPromptSection(slug: string): string {
	return [
		"# Memory",
		`You have a persistent memory system rooted at \`${memoryRoot()}/\`.`,
		"Use memory when the user asks to recall/remember, or when injected memory is clearly relevant. Treat memories as stale hints: verify file paths, functions, flags, and current repo state before acting.",
		"Do not save secrets, transient task state, derivable repo facts, git history, debugging recipes, or anything already documented in MEMORY.md, AGENTS.md, CLAUDE.md, or skill files.",
		"If the user explicitly asks you to save or forget a memory inline, use `write`/`edit` to update a typed markdown file plus the matching MEMORY.md index. Types: `user`, `feedback`, `project`, `reference`. Filenames must start with the type, e.g. `feedback_no_db_mocks.md`. Include frontmatter: `name`, `description`, `type`.",
		`Save cross-project memories under \`${profileDir()}/\`; save project-specific memories under \`${projectDir(slug)}/\`. Current project slug: \`${slug}\`.`,
		"For detailed save rules, load the `pi-memory-save` skill before writing non-trivial memories. Background extraction normally handles memory writes automatically.",
	].join("\n\n");
}

